import React, { createContext, useContext, useReducer, ReactNode, Dispatch } from 'react';
import { Sidebar, SidebarItem, SidebarUtilitiesItem } from '../store/Sidebar/SidebarService.types';

const initialState: Sidebar = {
  items: [],
  utils: [],
};

type Action = 
  | { type: 'SET_ITEMS'; payload: SidebarItem[] }
  | { type: 'SET_UTILS'; payload: SidebarUtilitiesItem[] };

const reducer = (state: Sidebar, action: Action): Sidebar => {
  switch (action.type) {
    case 'SET_ITEMS':
      return { ...state, items: action.payload };
    case 'SET_UTILS':
      return { ...state, utils: action.payload };
    default:
      return state;
  }
};

interface GlobalContextProps {
  state: Sidebar;
  dispatch: Dispatch<Action>;
}

const GlobalContext = createContext<GlobalContextProps | undefined>(undefined);

interface GlobalProviderProps {
  children: ReactNode;
}

export const GlobalProvider: React.FC<GlobalProviderProps> = ({ children }) => {
  const [state, dispatch] = useReducer(reducer, initialState);

  return (
    <GlobalContext.Provider value={{ state, dispatch }}>
      {children}
    </GlobalContext.Provider>
  );
};

export const useGlobalContext = (): GlobalContextProps | undefined => {
  const context = useContext(GlobalContext);
  return context;
};
